output_text:
[
  {
    "id": "no_carts_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where the aisle is too narrow for cart traffic.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "Agents must not enter a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_parked_cart_after_pedestrian_aisle",
    "text": "After leaving a cart to walk through a pedestrian-only shelf aisle, the agent is obliged to retrieve the cart before continuing to exit.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "cartParkingBay": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                8
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "leavePedestrianAisleWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle",
              "MOVE"
            ]
          },
          "post": "cartParkingBay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leavePedestrianAisleWithoutCart",
      "discharge": "hasCart"
    }
  },
  {
    "id": "park_cart_only_in_wide_bay",
    "text": "Carts may only be set down in wide open parking bays, not in shelf aisles or narrow passages.",
    "abstraction": {
      "state_properties": {
        "wideOpenArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                8
              ]
            }
          ]
        },
        "cartParkingBay": {
          "and": [
            "wideOpenArea",
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "cartParkingBay"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_at_cart_reachable_shelves",
    "text": "Shelf interactions from cart-reachable aisles must be performed with the cart, while very narrow pedestrian shelf aisles are treated as an exception.",
    "abstraction": {
      "state_properties": {
        "cartReachableShelfFront": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "hasCart"
          },
          "cartReachableShelfFront"
        ]
      }
    }
  },
  {
    "id": "hand_carry_in_single_file_shelf_aisle",
    "text": "Items taken from single-file shelf aisles must be hand-carried rather than collected while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "north_without_cart_only_into_pedestrian_aisles",
    "text": "Moving north without a cart is prohibited except when entering or already walking inside a pedestrian-only single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileOnFootNorthbound": {
          "pre": {
            "and": [
              "N",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "N",
          {
            "not": "hasCart"
          },
          {
            "not": "singleFileShelfAisle"
          },
          {
            "not": "enterSingleFileOnFootNorthbound"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_travel_in_broad_cart_corridors",
    "text": "Broad public cart corridors are reserved for shoppers with carts; cartless travel there is allowed only in the entrance/cart-rack area or at a pedestrian-aisle mouth.",
    "abstraction": {
      "state_properties": {
        "wideCartCorridor": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                8
              ]
            }
          ]
        },
        "entranceCartRackArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "pedestrianAisleMouth": "at(3,3)",
        "restrictedCartCorridor": {
          "and": [
            "wideCartCorridor",
            {
              "not": "entranceCartRackArea"
            },
            {
              "not": "pedestrianAisleMouth"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          "restrictedCartCorridor"
        ]
      }
    }
  }
]
